"use client";
import { forwardRef, type ReactNode } from "react";
import { motion, useReducedMotion, type HTMLMotionProps } from "framer-motion";
import { cn } from "@lib/utils";
import { spring } from "@lib/springs";
import { useTouchPrimary } from "@hooks/use-touch-primary";
import { ChatMessageAttachments } from "@ui/chat-message/attachments";
interface ChatMessageProps extends Omit<HTMLMotionProps<"div">, "children"> {
    /** Who sent the message. Drives alignment and bubble colour:
     *  `user` → right-aligned emphasis bubble, `assistant` → left-aligned plain text. */
    from: "user" | "assistant";
    /** Local file cards with a thumbnail and visible filename above the bubble. */
    files?: File[];
    /** Custom attachment content, including persisted remote files. */
    attachments?: ReactNode;
    /** Side length of each attachment thumbnail in pixels. Defaults to 64. */
    thumbnailSize?: number;
    /** Timestamp shown in the hover-revealed meta row, before the actions.
     *  User-message only — ignored on assistant replies. Caller pre-formats it
     *  (e.g. `"Wednesday 6:08 PM"`). */
    time?: ReactNode;
    /** Persistent identity above the message body, for example ChatMessageAuthor. */
    header?: ReactNode;
    /** Icon-only action buttons shown in the hover-revealed meta row (e.g. copy,
     *  edit, regenerate). Rendered next to the timestamp. */
    actions?: ReactNode;
    /** Additional metadata beside the actions, for example ChatMessageMeta.
     * Shares action visibility and wraps within the message width. */
    meta?: ReactNode;
    /** Keep actions visible for the latest reply or a custom touch layout. */
    actionsVisibility?: "auto" | "always";
    /** Message body. When omitted the text bubble is dropped (attachment-only message). */
    children?: ReactNode;
}
// ─── ChatMessage ──────────────────────────────────────────────────────────
// A single transcript entry with baked-in entrance + layout motion. Pairs with
// InputMessage's onSend: render one per sent/received message. `layout="position"`
// lets earlier messages slide up smoothly when a new one is appended.
/**
 * One message: role layout, body and optional identity, attachment and action slots.
 * Independent of ChatThread; the host owns message data and action callbacks.
 * Use ChatThread with ChatUserMessage/ChatAssistantMessage for conversation coordination.
 */
const ChatMessage = forwardRef<HTMLDivElement, ChatMessageProps>(({ from, files, attachments, thumbnailSize = 64, time, header, actions, meta, actionsVisibility = "auto", children, className, ...props }, ref) => {
    const isUser = from === "user";
    // Hover-reveal is unreachable on touch — keep the meta row visible there.
    const isTouch = useTouchPrimary();
    const reduceMotion = useReducedMotion();
    // Timestamps are a user-message affordance; assistant replies show actions only.
    const showTime = isUser && time != null;
    return (<motion.div ref={ref} data-slot="chat-message" layout="position" initial={reduceMotion ? false : { opacity: 0, y: 8, scale: 0.96 }} animate={{ opacity: 1, y: 0, scale: 1 }} transition={reduceMotion ? { duration: 0 } : spring.moderate} style={{ transformOrigin: isUser ? "bottom right" : "bottom left" }} className={cn("group flex min-w-0 flex-col gap-1.5", isUser ? "max-w-[80%] items-end self-end" : "w-full max-w-full items-start self-start", className)} {...props}>
        {header}
        {attachments}
        {files && files.length > 0 && (<ChatMessageAttachments files={files} thumbnailSize={thumbnailSize} align={isUser ? "end" : "start"}/>)}
        {children != null && children !== "" && (<div data-slot="chat-message-body" className={cn("min-w-0 max-w-full py-2 text-body whitespace-pre-wrap break-words", 
            // User keeps the bubble chrome (rounded fill + horizontal padding);
            // the assistant reply is flush-left plain text with no background.
            isUser
                ? cn("rounded-lg", 
                // `text-pretty` is reserved for settled user bubbles. On the
                // assistant reply it's left off on purpose: `text-wrap: pretty`
                // re-balances the last lines on every content change, so a
                // word-by-word stream visibly reflows earlier words to new
                // lines. Default (normal) wrapping appends left-to-right and
                // stays put as the text grows.
                "px-3.5 text-pretty bg-emphasis text-fg-default")
                : "w-full text-fg-default")}>
            {children}
          </div>)}
        {(showTime || actions != null || meta != null) && (
        // Meta row: timestamp + icon-only actions. Always rendered (so it
        // reserves its height and the gap between bubbles never shifts) but
        // hidden until the message is hovered or an action is focused.
        // The timestamp is a user-message affordance only — assistant replies
        // show their actions alone. User rows read date → icons left-to-right.
        <div data-slot="chat-message-footer" className={cn("flex min-w-0 max-w-full flex-wrap items-center gap-2 px-1 text-label leading-none text-fg-muted select-none", !isTouch && actionsVisibility !== "always" && [
                "opacity-0 pointer-events-none transition-opacity duration-moderate",
                "group-hover:opacity-100 group-hover:pointer-events-auto",
                "group-focus-within:opacity-100 group-focus-within:pointer-events-auto",
            ])}>
            {showTime && <span className="tabular-nums">{time}</span>}
            {actions != null && (<span className="flex min-w-0 max-w-full flex-wrap items-center gap-x-0.5 gap-y-1">{actions}</span>)}
            {meta != null && (<span className={cn("min-w-0 max-w-full", actions != null && "ml-1")}>
                {meta}
              </span>)}
          </div>)}
      </motion.div>);
});
ChatMessage.displayName = "ChatMessage";
export { ChatMessage };
export type { ChatMessageProps };
export { ChatMessageAction, ChatMessageCopy, ChatMessageBranchSwitch, } from "./chat-message/actions";
export type { ChatMessageActionProps, ChatMessageCopyProps, ChatMessageBranch, ChatMessageBranchSwitchProps, } from "./chat-message/actions";
export { ChatMessageAttachment, ChatMessageAttachments } from "./chat-message/attachments";
export type { ChatMessageFile, ChatMessageAttachmentProps, ChatMessageAttachmentsProps, } from "./chat-message/attachments";
export { ChatMessageEditor } from "./chat-message/editor";
export type { ChatMessageEditorProps } from "./chat-message/editor";
export { ChatMessageMeta } from "./chat-message/meta";
export type { ChatMessageMetrics, ChatMessageMetaProps } from "./chat-message/meta";
export { ChatMessageAuthor } from "./chat-message/author";
export type { ChatMessageAuthorProps } from "./chat-message/author";
export { ChatScrollToLatest, CHAT_SCROLL_FOLLOW_THRESHOLD } from "./chat-message/scroll-to-latest";
export type { ChatScrollToLatestProps } from "./chat-message/scroll-to-latest";
export default ChatMessage;

"use client";
import { useEffect, useRef, useState, type ReactNode } from "react";
import { Button } from "@ui/button";
import { Tooltip } from "@ui/tooltip";
import { useIcon } from "@lib/icon-context";
export interface ChatMessageActionProps {
    label: string;
    children: ReactNode;
    onClick: () => void;
    pressed?: boolean;
    disabled?: boolean;
}
export interface ChatMessageBranch {
    /** Zero-based active version; the host owns version contents. */
    index: number;
    count: number;
    onChange: (index: number) => void;
}
export interface ChatMessageCopyProps {
    text: string;
    disabled?: boolean;
    labels?: Partial<{
        copy: string;
        copied: string;
        copyFailed: string;
    }>;
}
export interface ChatMessageBranchSwitchProps {
    branch: ChatMessageBranch;
    disabled?: boolean;
    labels?: Partial<{
        previous: string;
        next: string;
        version: (index: number, count: number) => string;
    }>;
}
export function ChatMessageAction({ label, children, onClick, pressed, disabled, }: ChatMessageActionProps) {
    return (<Tooltip content={label}>
      <Button type="button" variant="ghost" size="sm" iconOnly aria-label={label} aria-pressed={pressed} active={pressed} disabled={disabled} onClick={onClick}>
        {children}
      </Button>
    </Tooltip>);
}
export function ChatMessageCopy({ text, disabled, labels: overrides }: ChatMessageCopyProps) {
    const labels = { copy: "Copy message", copied: "Copied", copyFailed: "Copy failed", ...overrides };
    const [notice, setNotice] = useState("");
    const request = useRef(0);
    const Copy = useIcon("copy");
    const Check = useIcon("check");
    useEffect(() => {
        setNotice("");
        return () => { request.current += 1; };
    }, [text]);
    useEffect(() => {
        if (!notice)
            return;
        const timer = setTimeout(() => setNotice(""), 2000);
        return () => clearTimeout(timer);
    }, [notice]);
    return (<>
      <ChatMessageAction label={labels.copy} disabled={disabled} onClick={async () => {
            const current = ++request.current;
            try {
                await navigator.clipboard.writeText(text);
                if (current === request.current)
                    setNotice(labels.copied);
            }
            catch {
                if (current === request.current)
                    setNotice(labels.copyFailed);
            }
        }}>
        {notice === labels.copied ? <Check /> : <Copy />}
      </ChatMessageAction>
      <span className="sr-only" role="status">
        {notice}
      </span>
    </>);
}
export function ChatMessageBranchSwitch({ branch, disabled = false, labels: overrides, }: ChatMessageBranchSwitchProps) {
    const labels = { previous: "Previous version", next: "Next version", version: (index: number, count: number) => `Version ${index} of ${count}`, ...overrides };
    const Previous = useIcon("chevron-left");
    const Next = useIcon("chevron-right");
    if (!Number.isInteger(branch.count) ||
        branch.count < 2 ||
        !Number.isInteger(branch.index) ||
        branch.index < 0 ||
        branch.index >= branch.count)
        return null;
    return (<span role="group" aria-label={labels.version(branch.index + 1, branch.count)} className="inline-flex items-center gap-1">
      <ChatMessageAction label={labels.previous} disabled={disabled || branch.index === 0} onClick={() => branch.onChange(branch.index - 1)}>
        <Previous />
      </ChatMessageAction>
      <span className="text-label tabular-nums text-fg-muted">
        {branch.index + 1} / {branch.count}
      </span>
      <ChatMessageAction label={labels.next} disabled={disabled || branch.index === branch.count - 1} onClick={() => branch.onChange(branch.index + 1)}>
        <Next />
      </ChatMessageAction>
    </span>);
}

"use client";
import { FileThumbnail } from "@ui/file-thumbnail";
import { useIcon } from "@lib/icon-context";
import { cn } from "@lib/utils";
function safeFileUrl(url?: string) {
    if (!url)
        return undefined;
    try {
        const parsed = new URL(url, "https://local.invalid");
        return ["http:", "https:", "blob:"].includes(parsed.protocol) ? url : undefined;
    }
    catch {
        return undefined;
    }
}
export interface ChatMessageFile {
    id: string;
    name: string;
    /** File size in bytes. */
    size?: number;
    type?: string;
    /** HTTP(S), blob or relative URL; other protocols are ignored. */
    url?: string;
}
export interface ChatMessageAttachmentProps {
    file: ChatMessageFile | File;
    /** Shared square size for image previews and file icons. */
    thumbnailSize?: number;
}
export interface ChatMessageAttachmentsProps {
    files: readonly (ChatMessageFile | File)[];
    align?: "start" | "end";
    label?: string;
    thumbnailSize?: number;
}
function isLocalFile(file: ChatMessageFile | File): file is File {
    return "lastModified" in file;
}
/** One border owns the preview and visible file details, for local and persisted files. */
export function ChatMessageAttachment({ file, thumbnailSize = 64 }: ChatMessageAttachmentProps) {
    const FileIcon = useIcon("file");
    const local = isLocalFile(file);
    const url = local ? undefined : safeFileUrl(file.url);
    const image = file.type?.startsWith("image/") && url;
    const body = (<span data-slot="chat-message-attachment" className="flex min-w-0 max-w-64 items-center gap-3 rounded-lg border border-border bg-surface-raised p-2 text-label">
      <span data-slot="chat-message-attachment-preview" className="flex shrink-0 items-center justify-center overflow-hidden rounded-md" style={{ width: thumbnailSize, height: thumbnailSize }}>
        {local && (file.type.startsWith("image/") || file.type === "application/pdf") ? (<FileThumbnail file={file} size={thumbnailSize} bordered={false}/>) : image ? (
        // Persisted attachments are URLs, not synthetic browser File objects.
        // eslint-disable-next-line @next/next/no-img-element
        <img src={url} alt={file.name} width={thumbnailSize} height={thumbnailSize} className="size-full object-cover"/>) : (<FileIcon size={thumbnailSize}/>)}
      </span>
      <span className="min-w-0">
        <span className="block truncate" title={file.name}>{file.name}</span>
        {file.size != null && Number.isFinite(file.size) && file.size >= 0 && (<span className="block text-fg-muted">{Math.ceil(file.size / 1024)} KB</span>)}
      </span>
    </span>);
    return url ? (<a href={url} target="_blank" rel="noopener noreferrer" aria-label={file.name} className="block max-w-full rounded-lg outline-none focus-visible:ring-1 focus-visible:ring-focus-ring">
      {body}
    </a>) : body;
}
export function ChatMessageAttachments({ files, align = "end", label = "Attachments", thumbnailSize = 64 }: ChatMessageAttachmentsProps) {
    return (<ul className={cn("flex max-w-full flex-wrap gap-2", align === "end" ? "justify-end" : "justify-start")} aria-label={label}>
      {files.map((file, index) => (<li key={isLocalFile(file) ? `${file.name}-${file.size}-${file.lastModified}-${index}` : file.id} className="min-w-0 max-w-full">
          <ChatMessageAttachment file={file} thumbnailSize={thumbnailSize}/>
        </li>))}
    </ul>);
}

"use client";
import { useEffect, useRef, useState } from "react";
import { Button } from "@ui/button";
import { Textarea } from "@ui/textarea";
import { InlineNotice, InlineNoticeContent } from "@ui/inline-notice";
export interface ChatMessageEditorProps {
    text: string;
    onSave: (text: string) => void | Promise<void>;
    /** Called on cancellation, unchanged text, or successful save. */
    onCancel: () => void;
    /** Freeze an existing draft while the host changes conversation history. */
    disabled?: boolean;
    labels?: Partial<{
        edit: string;
        cancel: string;
        save: string;
        saveFailed: string;
    }>;
}
export function ChatMessageEditor({ text, onSave, onCancel, disabled = false, labels: overrides, }: ChatMessageEditorProps) {
    const labels = { edit: "Edit message", cancel: "Cancel", save: "Save", saveFailed: "Could not save. Try again.", ...overrides };
    const [draft, setDraft] = useState(text);
    const [pending, setPending] = useState(false);
    const [error, setError] = useState(false);
    const ref = useRef<HTMLTextAreaElement>(null);
    const lock = useRef(false);
    useEffect(() => {
        ref.current?.focus();
        ref.current?.setSelectionRange(text.length, text.length);
    }, [text]);
    const save = async () => {
        if (disabled || !draft.trim() || lock.current)
            return;
        if (draft.trim() === text) {
            onCancel();
            return;
        }
        lock.current = true;
        setPending(true);
        setError(false);
        try {
            await onSave(draft.trim());
            onCancel();
        }
        catch {
            setError(true);
        }
        finally {
            lock.current = false;
            setPending(false);
        }
    };
    return (<div className="w-full space-y-2">
      <Textarea ref={ref} aria-label={labels.edit} value={draft} rows={3} disabled={disabled || pending} onChange={(event) => setDraft(event.target.value)} onKeyDown={(event) => {
            if (event.nativeEvent.isComposing || event.keyCode === 229)
                return;
            if (event.key === "Escape" && !pending) {
                event.preventDefault();
                onCancel();
            }
            if (event.key === "Enter" && !event.shiftKey) {
                event.preventDefault();
                void save();
            }
        }}/>
      {error && (<InlineNotice role="alert" variant="emphasized" tone="danger">
          <InlineNoticeContent>{labels.saveFailed}</InlineNoticeContent>
        </InlineNotice>)}
      <div className="flex justify-end gap-2">
        <Button variant="ghost" size="sm" disabled={pending} onClick={onCancel}>
          {labels.cancel}
        </Button>
        <Button variant="neutral" size="sm" disabled={disabled || !draft.trim()} loading={pending} onClick={() => void save()}>
          {labels.save}
        </Button>
      </div>
    </div>);
}

import type { HTMLAttributes, ReactNode } from "react";
import { cn } from "@lib/utils";
export interface ChatMessageAuthorProps extends Omit<HTMLAttributes<HTMLDivElement>, "children"> {
    model?: ReactNode;
    /** Decorative model artwork. The visible model name provides its text alternative. */
    logo?: ReactNode;
    provider?: ReactNode;
}
/** Persistent response identity, independent of the hover-revealed action row. */
export function ChatMessageAuthor({ model, logo, provider, className, ...props }: ChatMessageAuthorProps) {
    if (model == null && logo == null && provider == null)
        return null;
    return (<div data-slot="chat-message-author" className={cn("flex min-w-0 max-w-full flex-wrap items-center gap-x-2 gap-y-1 text-body", className)} {...props}>
      {logo != null && (<span aria-hidden="true" inert className="inline-flex size-4 shrink-0 items-center justify-center [&>svg]:size-full [&>img]:size-full [&>img]:object-contain">
          {logo}
        </span>)}
      {model != null && <span className="min-w-0 break-words font-medium text-fg-default">{model}</span>}
      {provider != null && <span className="min-w-0 break-words text-fg-muted">{provider}</span>}
    </div>);
}

"use client";
import type { MouseEventHandler } from "react";
import { Button } from "@ui/button";
import { useIcon } from "@lib/icon-context";
import { cn } from "@lib/utils";
/** Distance in pixels at which a conversation is considered to be at its latest content. */
export const CHAT_SCROLL_FOLLOW_THRESHOLD = 24;
export interface ChatScrollToLatestProps {
    onClick: MouseEventHandler<HTMLButtonElement>;
    label?: string;
    locale?: string;
    disabled?: boolean;
    /** Position the overlay relative to the host's scroll region or composer. */
    className?: string;
}
/** Shared navigation affordance. The host owns visibility, scrolling and following. */
export function ChatScrollToLatest({ onClick, label, locale = "en", disabled, className }: ChatScrollToLatestProps) {
    const ArrowDown = useIcon("arrow-down");
    return (<div data-slot="chat-scroll-to-latest" className={cn("pointer-events-none absolute inset-x-0 bottom-4 z-raised flex justify-center", className)}>
      <Button type="button" variant="tertiary" size="sm" leadingIcon={ArrowDown} disabled={disabled} onClick={onClick} className="pointer-events-auto">
        {label ?? (locale.startsWith("zh") ? "回到最新内容" : "Scroll to latest")}
      </Button>
    </div>);
}

import type { ReactNode } from "react";
const compactTokens = new Intl.NumberFormat("en-US", { notation: "compact", maximumFractionDigits: 1 });
const billions = new Intl.NumberFormat("en-US", { maximumFractionDigits: 1 });
const tokenText = (value: number) => value >= 1e9
    ? `${billions.format(value / 1e9)}B`
    : compactTokens.format(value).replace(/K$/, "k");
export interface ChatMessageMetrics {
    /** Time to the first output token, in milliseconds. */
    ttftMs?: number;
    inputTokens?: number;
    outputTokens?: number;
    /** Total response duration, in milliseconds. */
    durationMs?: number;
}
export interface ChatMessageMetaProps {
    model?: ReactNode;
    metrics?: ChatMessageMetrics;
    locale?: string;
    labels?: Partial<{
        ttft: string;
        inputTokens: string;
        outputTokens: string;
        duration: string;
    }>;
}
/** Response metadata; supplied values belong to this reply, not the active model selector. */
export function ChatMessageMeta({ model, metrics, locale = "en", labels: overrides }: ChatMessageMetaProps) {
    const zh = locale.startsWith("zh");
    const labels = { ttft: "TTFT", inputTokens: zh ? "输入" : "Input", outputTokens: zh ? "输出" : "Output", duration: zh ? "耗时" : "Time", ...overrides };
    let numbers: Intl.NumberFormat;
    try {
        numbers = new Intl.NumberFormat(locale, { maximumFractionDigits: 2 });
    }
    catch {
        numbers = new Intl.NumberFormat("en", { maximumFractionDigits: 2 });
    }
    const duration = (ms: number) => ms < 1000 ? `${numbers.format(Math.round(ms))} ms` : `${numbers.format(ms / 1000)} s`;
    const fields = [
        { key: "ttft", label: labels.ttft, value: metrics?.ttftMs, format: duration },
        { key: "input", label: labels.inputTokens, value: metrics?.inputTokens, format: (n: number) => `${tokenText(n)} tokens`, integer: true },
        { key: "output", label: labels.outputTokens, value: metrics?.outputTokens, format: (n: number) => `${tokenText(n)} tokens`, integer: true },
        { key: "duration", label: labels.duration, value: metrics?.durationMs, format: duration },
    ].filter(({ value, integer }) => value != null && Number.isFinite(value) && value >= 0 && (!integer || Number.isInteger(value)));
    if (model == null && !fields.length)
        return null;
    return (<span data-slot="chat-message-meta" className="inline-flex min-w-0 max-w-full flex-wrap items-center gap-x-3 gap-y-1 text-label text-fg-muted tabular-nums">
      {model != null && <span className="min-w-0 break-words">{model}</span>}
      {fields.map(({ key, label, value, format, integer }) => {
            const display = `${label} ${format(value!)}`;
            const exact = integer ? `${label} ${numbers.format(value!)} tokens` : undefined;
            return <span key={key} title={exact} className="whitespace-nowrap">{exact
                    ? <><span aria-hidden="true">{display}</span><span className="sr-only">{exact}</span></>
                    : display}</span>;
        })}
    </span>);
}
